def largest_prime_factor(n: int):
    assert n > 1 and not is_prime(n), "Input must be an integer greater than 1 and not prime"
    factor = 1
    while n % 2 == 0:
        factor = 2
        n //= 2
    while n % factor != 0:
        factor += 1
    while factor * factor <= n:
        while n % factor == 0:
            n //= factor
        factor += 2
    return n if factor * factor <= n else factor
